/**
 * Every analytics event the site sends.
 *
 * Dispatches window.gtag('event', name, params) -> Google Analytics 4
 * (Property 262743198 / GA_MEASUREMENT_ID). GTM/Bing Ads is not used.
 *
 * Events go through the typed helpers below rather than `trackEvent` directly,
 * so the set of event names is the set of methods here. There used to be a
 * second, untyped `gtagEvent` path alongside this one, carrying Universal
 * Analytics' event_category/event_label vocabulary that GA4 has no use for —
 * ten components fired both and every action was counted twice.
 */
import { CURRENCY, INTRO_PRICE, ONE_TIME_PRICE } from "~/utils/pricing";
import { cleanPath, contentGroupFor } from "~/utils/cleanPath";

export { cleanPath, contentGroupFor };
/* eslint-disable no-unused-vars -- ambient type declaration, not a real binding */
declare global {
  interface Window {
    dataLayer?: unknown[];
    gtag?: (...args: unknown[]) => void;
  }
}
/* eslint-enable no-unused-vars */

/**
 * Where an AI analysis was asked for: the AI tool page, the analyzer's
 * results, the cloud offered after the on-device AI couldn't run, or a
 * reading someone sent (pages/s.vue).
 */
export type AiSource = "tool" | "results" | "fallback" | "shared";

export interface EventParams {
  [key: string]: string | number | boolean | null | undefined;
}

/**
 * Ensures gtag function exists on window, matching the official gtag.js bootstrap.
 * This guarantees events called before or after gtag.js loads are queued and processed.
 */
function ensureGtag(): boolean {
  if (typeof window === "undefined") return false;

  window.dataLayer = window.dataLayer || [];
  if (typeof window.gtag !== "function") {
    // `arguments`, not a rest array: gtag.js only replays Arguments objects
    // off the dataLayer and silently skips plain arrays.
    window.gtag = function () {
      window.dataLayer?.push(arguments);
    };
  }
  return true;
}

/**
 * Sanitizes event names to adhere to GA4 rules:
 * - 1 to 40 characters
 * - Only alphanumeric and underscores
 * - Must start with a letter
 * - Lowercase snake_case
 */
export function sanitizeEventName(rawName: string): string {
  if (!rawName) return "custom_event";

  // Replace spaces, dashes, dots with underscores
  let name = rawName
    .trim()
    .replace(/[\s\-.]+/g, "_")
    // Remove any character that is not alphanumeric or underscore
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();

  // Ensure it starts with a letter (prefix with 'ev_' if it starts with digit or underscore)
  if (!/^[a-z]/.test(name)) {
    name = `ev_${name}`;
  }

  // Cap at 40 characters
  return name.slice(0, 40);
}

/**
 * Sanitizes event parameters:
 * - Parameter names must be valid snake_case identifiers
 * - Strings trimmed and capped at 100 characters
 * - Numbers kept as numbers (not stringified)
 * - Undefined/null/NaN cleaned up
 */
export function sanitizeParams(
  rawParams?: EventParams,
): Record<string, string | number | boolean> {
  if (!rawParams) return {};

  const clean: Record<string, string | number | boolean> = {};

  for (const [key, val] of Object.entries(rawParams)) {
    if (val === undefined || val === null) continue;

    // Clean key
    const cleanKey = key
      .trim()
      .replace(/[\s\-.]+/g, "_")
      .replace(/[^a-zA-Z0-9_]/g, "")
      .toLowerCase()
      .slice(0, 40);

    if (!cleanKey) continue;

    if (typeof val === "number") {
      if (Number.isFinite(val)) {
        clean[cleanKey] = Math.round(val * 100) / 100;
      }
    } else if (typeof val === "boolean") {
      clean[cleanKey] = val;
    } else {
      const strVal = String(val).trim().slice(0, 100);
      clean[cleanKey] = strVal;
    }
  }

  return clean;
}

/** A GA4 ecommerce item. Ids match what the Stripe webhook reports. */
export interface AnalyticsItem {
  item_id: string;
  item_name: string;
  price: number;
  quantity: number;
}

export const ITEM_FULL_PDF: AnalyticsItem = {
  item_id: "full_chat_pdf",
  item_name: "Full Chat PDF",
  price: ONE_TIME_PRICE,
  quantity: 1,
};

// Priced at the intro month, which is what checkout charges.
export const ITEM_PRO_SUBSCRIPTION: AnalyticsItem = {
  item_id: "pro_subscription",
  item_name: "WhatsAnalyze Pro Subscription",
  price: INTRO_PRICE,
  quantity: 1,
};

export type ContentGroup = string;

/**
 * Re-exported for backwards compatibility and single-source canonical pathing.
 */

export const GA_MEASUREMENT_ID = "G-XYC2EWGZZ3";

/**
 * Tags every following page_view and event with the canonical page path.
 * Without send_page_view:false every call would add a page_view of its own.
 */
export function setContentGroup(path: string): void {
  if (!ensureGtag()) return;
  const clean = contentGroupFor(path);
  window.gtag?.("config", GA_MEASUREMENT_ID, {
    content_group: clean,
    clean_path: clean,
    send_page_view: false,
  });
}

/**
 * Core event tracking function. `items` bypasses sanitizeParams, which would
 * stringify the array.
 */
export function trackEvent(
  name: string,
  params?: EventParams,
  items?: AnalyticsItem[],
): void {
  if (!ensureGtag()) return;

  const eventName = sanitizeEventName(name);
  const cleanParams: Record<string, unknown> = sanitizeParams(params);
  if (items) cleanParams.items = items;
  if (!cleanParams.clean_path && typeof window !== "undefined") {
    cleanParams.clean_path = cleanPath(window.location.pathname);
  }
  try {
    if (typeof window.gtag === "function") {
      window.gtag("event", eventName, cleanParams);
    }
  } catch (err) {
    if (process.env.NODE_ENV !== "production") {
      console.warn("[Analytics] Failed to track event:", eventName, err);
    }
  }
}

