/**
 * E-Commerce & Subscriptions
 */
export const analyticsEcommerce = {
  /**
   * The price of something was put in front of the visitor: a paywall, the
   * pricing card, the subscribe page. First step of GA's Purchase journey.
   */
  viewItem(source: string, item: AnalyticsItem, sourcePage?: string) {
    trackEvent(
      "view_item",
      {
        source,
        // Where the visitor came to the price from, e.g. the AI analyzer.
        source_page: sourcePage ? cleanPath(sourcePage) : undefined,
        currency: CURRENCY,
        value: item.price,
      },
      [item],
    );
  },

  /** A click on a "subscribe"/"get Pro" link that leads to the pricing. */
  pricingCtaClick(source: string) {
    trackEvent("pricing_cta_click", { source });
  },

  /**
   * The visitor picked a plan and is sent to Stripe. There is no cart, so
   * add_to_cart and begin_checkout are the same click; both are sent because
   * GA's Purchase and Checkout journeys each start from one of them. Amounts
   * come from utils/pricing.ts, which the Stripe prices are configured with.
   */
  beginCheckout(options: {
    checkoutType: "subscription" | "one_time";
    source: string;
    /** The page the visitor came to the price from, as for viewItem. */
    sourcePage?: string;
  }) {
    const item =
      options.checkoutType === "subscription"
        ? ITEM_PRO_SUBSCRIPTION
        : ITEM_FULL_PDF;
    const params = {
      checkout_type: options.checkoutType,
      source: options.source,
      source_page: options.sourcePage
        ? cleanPath(options.sourcePage)
        : undefined,
      currency: CURRENCY,
      value: item.price,
    };
    trackEvent("add_to_cart", params, [item]);
    trackEvent("begin_checkout", params, [item]);
  },

  // No `purchase` here on purpose. It is sent from the Stripe webhook
  // (`functions/src/analytics/measurementProtocol.ts`), which sees every
  // paid cent plus the renewals no browser is around for. GA4 does not
  // deduplicate by transaction id, so exactly one sender may exist.

  /**
   * Back from Stripe with a paid session. Deliberately not `purchase` —
   * that one is the webhook's, and GA4 does not deduplicate.
   */
  checkoutCompleted(checkoutType: "subscription" | "one_time", source: string) {
    trackEvent("checkout_completed", {
      checkout_type: checkoutType,
      source,
    });
  },

  checkoutCancelled(source: string) {
    trackEvent("checkout_cancelled", { source });
  },

  customerPortalOpened(subscriptionId?: string) {
    trackEvent("customer_portal_opened", {
      subscription_id: subscriptionId || "unknown",
    });
  },

  subscriptionVerified(method: "auto_param" | "manual_code" | "email_link") {
    trackEvent("subscription_verified", { method });
  },
};

/**
 * Where an AI analysis ran; "preview" is the free, shortened cloud run, and
 * "sample" the sample chat's reading, made in advance (utils/ai/sample.ts).
 */
type AiMode = "local" | "cloud" | "preview" | "sample";

/**
 * Standalone Tools (/tools/* and ToolDropzone)
 */
export const analyticsTools = {
  hubClick(toolName: string) {
    trackEvent("tool_hub_click", { tool_name: toolName });
  },

  fileUploaded(
    toolName: string,
    fileType: "txt" | "zip" | "other",
    source: "drop" | "picker" = "picker",
  ) {
    const sourcePage =
      typeof window !== "undefined"
        ? cleanPath(window.location.pathname)
        : `/tools/${toolName}/`;
    trackEvent("tool_file_uploaded", {
      tool_name: toolName,
      file_type: fileType,
      upload_source: source,
      source_page: sourcePage,
    });
    trackEvent("file_upload_started", {
      file_type: fileType,
      upload_method: source,
      tool_name: toolName,
      source_page: sourcePage,
    });
  },

  sampleLoaded(toolName: string) {
    trackEvent("tool_sample_loaded", { tool_name: toolName });
  },

  analyzed(toolName: string, messageCount: number, durationMs?: number) {
    trackEvent("tool_analyzed", {
      tool_name: toolName,
      message_count: messageCount,
      duration_ms: durationMs ? Math.round(durationMs) : undefined,
    });
  },

  /**
   * An AI analysis was started, on the device or in the cloud.
   * `background`: whether the reader said what the chat doesn't show.
   */
  aiStarted(
    mode: AiMode,
    question: string,
    source: AiSource,
    background: boolean,
  ) {
    // The preset's id or "custom", never what was typed; nor the background.
    trackEvent("ai_analysis_started", {
      ai_mode: mode,
      ai_question: question,
      source,
      ai_background: background,
    });
  },

  /** The mobile-data warning before the on-device model download. */
  aiDataWarning(reason: "cellular" | "unknown") {
    trackEvent("ai_data_warning", { reason });
  },

  aiFinished(mode: AiMode, durationMs: number, source: AiSource) {
    trackEvent("ai_analysis_finished", {
      ai_mode: mode,
      source,
      duration_ms: Math.round(durationMs),
    });
  },

  /**
   * An AI analysis ended in an error: a known code or the raw message.
   * `phase` is where, as for aiAbandoned: download, read, write or cloud.
   */
  aiFailed(mode: AiMode, reason: string, phase?: string) {
    trackEvent("ai_analysis_failed", {
      ai_mode: mode,
      reason: reason.slice(0, 100),
      phase,
    });
  },

  /**
   * The on-device AI isn't offered on this device, and why: no_webgpu,
   * no_adapter, gpu_limits, gpu_device or storage (utils/ai/localCheck.js).
   */
  aiLocalUnavailable(reason: string) {
    trackEvent("ai_local_unavailable", { reason });
  },

  /**
   * The visitor gave up: left the page mid-run, or turned down the mobile-data
   * download. `phase` is where: data_warning, download, read, write or cloud.
   */
  aiAbandoned(mode: AiMode, phase: string, durationMs = 0) {
    trackEvent("ai_analysis_abandoned", {
      ai_mode: mode,
      phase,
      duration_ms: Math.round(durationMs),
    });
  },

  /**
   * A follow-up sent to the AI coach after a report. Never its text, nor the
   * reader's background: only whether there was one.
   */
  aiCoachMessage(
    mode: "local" | "cloud" | "sample",
    kind: "ask" | "reply",
    background: boolean,
  ) {
    trackEvent("ai_coach_message", {
      ai_mode: mode,
      coach_kind: kind,
      ai_background: background,
    });
  },

  /** The coach showed support resources instead of an answer. */
  aiCoachSafety(source: "keywords" | "model") {
    trackEvent("ai_coach_safety", { source });
  },

  /*
   * A reading sent to the other person in the chat (utils/ai/sendReading.js):
   * previewed, sent through WhatsApp, opened by them, and their own reading
   * after it. `question` is the preset's id or "none", the only things that
   * can be sent. Never names, the reading or the link.
   */
  aiSharePreviewed(question: string) {
    trackEvent("ai_share_previewed", { ai_question: question });
  },

  aiShareSent(question: string) {
    trackEvent("ai_share_sent", { ai_question: question, method: "whatsapp" });
  },

  aiShareOpened(question: string) {
    trackEvent("ai_share_opened", { ai_question: question });
  },

  /** Whoever opened a sent reading finished one of their own chat. */
  aiShareConverted(mode: AiMode, question: string) {
    trackEvent("ai_share_converted", { ai_mode: mode, ai_question: question });
  },

  error(toolName: string, errorCode: string) {
    trackEvent("tool_error", {
      tool_name: toolName,
      error_code: errorCode,
    });
  },

  ctaClick(
    toolName: string,
    ctaType:
      | "full_analyzer"
      | "export_guide"
      | "subscribe"
      | "ai"
      | "scroll_to_dropzone"
      | "hero_dropzone"
      | "sample"
      | "other",
  ) {
    trackEvent("tool_cta_click", {
      tool_name: toolName,
      cta_type: ctaType,
    });
  },
};

/**
 * Core Chat Analyzer (Main flow)
 */
export const analyticsChat = {
  uploadStarted(
    fileType: "txt" | "zip" | "other",
    uploadMethod: "drop" | "picker" | "shared" = "picker",
    sourcePage?: string,
  ) {
    trackEvent("file_upload_started", {
      file_type: fileType,
      upload_method: uploadMethod,
      source_page:
        sourcePage ||
        (typeof window !== "undefined"
          ? cleanPath(window.location.pathname)
          : undefined),
    });
  },

  parsedSuccess(
    messageCount: number,
    participantCount?: number,
    durationMs?: number,
  ) {
    trackEvent("file_parsed_success", {
      message_count: messageCount,
      participant_count: participantCount,
      duration_ms: durationMs ? Math.round(durationMs) : undefined,
    });
  },

  parsedError(errorCode: string) {
    trackEvent("file_parsed_error", {
      error_code: sanitizeEventName(errorCode),
    });
  },

  chatAnalyzed(participantCount: number, isGroup: boolean) {
    trackEvent("chat_analyzed", {
      chat_type: isGroup ? "group" : "pair",
      participant_count: participantCount,
    });
  },

  participantChanged() {
    trackEvent("select_participant", { action: "change_ego" });
  },

  share(
    method: "native_share" | "clipboard" | "image_download",
    contentType: string,
  ) {
    trackEvent("share", {
      method,
      content_type: contentType,
    });
  },

  /** Someone opened a highlights share link instead of analyzing a chat. */
  sharedHighlightsOpened() {
    trackEvent("shared_highlights_view");
  },

  download(
    fileType: "pdf_sample" | "pdf_full" | "pdf_full_court" | "chart_image",
    chartName?: string,
  ) {
    trackEvent("file_download", {
      file_type: fileType,
      chart_name: chartName,
    });
  },
};

